    pos = point(1, "P", p);
    col = point(1, "Cd", p);
    d = length(@P - pos);
    d = fit(d, 0, ch("radius"), 1, 0);

    // offset the ramp so its mostly 0,
    // then suddenly 1 at the end
    // (chramp is clamped)

    // lerp is interpolate, we use d to make the colour
    // mostly the point colour, then quickly fade to
    // white at the radius border
    col = lerp(col, 1, d);

    // multiply the colour
    @Cd *= col;
}

