pcg = pcfilter(pc, 'P');
pcg = pcfilter(pc, 'P');

dot = dot(@N, pcg);
dist = distance(@P, pcg);

dot = chramp('dot_cc', dot);
dist = chramp('dist_cc', dist);

@Cd = dot;
